  { id: 'cold', name: 'COLD STORE', sub: 'south-east', x: 640, y: 420, w: 580, h: 340, tint: '#152630', accent: '#5aa9ff' },
];

// Solid walls, drawn as slabs. Doorways are the gaps between them.
export const WALLS = [
