function drawFloorGrid(ctx) {
  ctx.strokeStyle = PALETTE.grid;
  ctx.lineWidth = 1;
  ctx.beginPath();
  for (let x = 60; x <= 1220; x += 40) {
    ctx.moveTo(x + 0.5, 80);
    ctx.lineTo(x + 0.5, 760);
  }
  for (let y = 80; y <= 760; y += 40) {
    ctx.moveTo(60, y + 0.5);
    ctx.lineTo(1220, y + 0.5);
